ALTER TABLE "sliper"."event_settings" ADD COLUMN "meetup_type" varchar(16) DEFAULT 'event' NOT NULL;--> statement-breakpoint
ALTER TABLE "sliper"."event_settings" ADD COLUMN "venue_latitude" double precision;--> statement-breakpoint
ALTER TABLE "sliper"."event_settings" ADD COLUMN "venue_longitude" double precision;--> statement-breakpoint
CREATE INDEX "event_venue_idx" ON "sliper"."event_settings" USING btree ("venue_latitude","venue_longitude") WHERE "sliper"."event_settings"."venue_latitude" is not null;--> statement-breakpoint
ALTER TABLE "sliper"."event_settings" ADD CONSTRAINT "event_meetup_type" CHECK ("sliper"."event_settings"."meetup_type" in ('event','lightning'));--> statement-breakpoint
ALTER TABLE "sliper"."event_settings" ADD CONSTRAINT "event_venue_pair" CHECK (("sliper"."event_settings"."venue_latitude" is null) = ("sliper"."event_settings"."venue_longitude" is null));--> statement-breakpoint
ALTER TABLE "sliper"."event_settings" ADD CONSTRAINT "event_venue_range" CHECK ("sliper"."event_settings"."venue_latitude" between -90 and 90 and "sliper"."event_settings"."venue_longitude" between -180 and 180);--> statement-breakpoint
ALTER TABLE "sliper"."event_settings" ADD CONSTRAINT "event_lightning_rules" CHECK ("sliper"."event_settings"."meetup_type" <> 'lightning' or ("sliper"."event_settings"."amount_krw"=0 and "sliper"."event_settings"."capacity" between 2 and 12 and "sliper"."event_settings"."starts_at" is not null and "sliper"."event_settings"."ends_at" is not null and "sliper"."event_settings"."venue_latitude" is not null and "sliper"."event_settings"."venue_longitude" is not null and "sliper"."event_settings"."starts_at">"sliper"."event_settings"."created_at" and "sliper"."event_settings"."starts_at"<="sliper"."event_settings"."created_at"+interval '7 days' and "sliper"."event_settings"."ends_at">="sliper"."event_settings"."starts_at"+interval '15 minutes' and "sliper"."event_settings"."ends_at"<="sliper"."event_settings"."starts_at"+interval '12 hours'));